INSERT INTO webdav_resource(song_id,source_id,binding,relative_path,path_hash,task_id,last_seen_at,identity_size,identity_modified,file_size,modified_at) SELECT s.id,s.source_id,@{binding},s.relative_path,s.path_hash,s.id,s.scanned_at,s.file_size,s.modified_at,s.file_size,s.modified_at FROM media_song s WHERE s.source_id=@{sourceId} AND (@{songId} IS NULL OR s.id=@{songId}) AND NOT EXISTS(SELECT 1 FROM webdav_resource r WHERE r.song_id=s.id)
